 52	function question(input, output, prompt, hidden) {
 53	  return new Promise((resolve, reject) => {
 54	    let settled = false;
 55	    let muted = false;
 56	    const terminalOutput = hidden
 57	      ? new Writable({
 58	        write(chunk, encoding, callback) {
 59	          if (!muted) output.write(chunk, encoding);
 60	          callback();
 61	        },
 62	      })
 63	      : output;
 64	    const rl = createInterface({ input, output: terminalOutput, terminal: true });
 65	    const finish = (callback) => {
 66	      if (settled) return;
 67	      settled = true;
 68	      rl.close();
 69	      if (hidden) output.write('\n');
 70	      callback();
 71	    };
 72	    rl.once('SIGINT', () => finish(() => reject(new SetupCancelledError())));
 73	    rl.once('close', () => {
 74	      if (!settled) finish(() => reject(new SetupCancelledError()));
 75	    });
 76	    rl.question(prompt, (answer) => finish(() => resolve(answer)));
 77	    muted = hidden;
 78	  });
 79	}
