 81	export function createTerminalIo(options = {}) {
 82	  const input = options.stdin ?? process.stdin;
 83	  const output = options.stdout ?? process.stdout;
 84	  return {
 85	    isTTY: Boolean(input.isTTY && output.isTTY),
 86	    write(line) {
 87	      output.write(`${line}\n`);
 88	    },
 89	    prompt(message) {
 90	      return question(input, output, message, false);
 91	    },
 92	    secret(message) {
 93	      return question(input, output, message, true);
 94	    },
 95	    async confirm(message, defaultValue = true) {
 96	      for (;;) {
 97	        const suffix = defaultValue ? ' [Y/n] ' : ' [y/N] ';
 98	        const answer = (await question(input, output, `${message}${suffix}`, false)).trim().toLowerCase();
 99	        if (!answer) return defaultValue;
100	        if (answer === 'y' || answer === 'yes') return true;
101	        if (answer === 'n' || answer === 'no') return false;
102	        output.write('请输入 y 或 n。\n');
103	      }
104	    },
105	    async select(message, choices, defaultIndex = 0) {
106	      for (;;) {
107	        const answer = (await question(
108	          input,
109	          output,
110	          `${message} [${defaultIndex + 1}] `,
111	          false,
112	        )).trim();
113	        const index = answer === '' ? defaultIndex : Number(answer) - 1;
114	        if (Number.isInteger(index) && index >= 0 && index < choices.length) return choices[index].value;
115	        output.write(`请输入 1-${choices.length}。\n`);
116	      }
117	    },
118	  };
119	}
