198	        fileSystem.writeFileSync(descriptor, `${JSON.stringify(entry.value, null, 2)}\n`, 'utf8');
199	        fileSystem.fsyncSync(descriptor);
200	      } finally {
201	        fileSystem.closeSync(descriptor);
202	      }
203	      if (platform === 'win32') protectFile(tempPath);
204	      else fileSystem.chmodSync(tempPath, 0o600);
205	    }
206	
207	    for (const item of prepared) {
208	      const replacement = {
209	        ...item,
210	        hadOriginal: fileSystem.existsSync(item.path),
211	        installed: false,
212	      };
213	      replacements.push(replacement);
214	      if (replacement.hadOriginal) {
215	        if (platform === 'win32') protectFile(item.path);
216	        fileSystem.renameSync(item.path, item.backupPath);
217	      }
218	      fileSystem.renameSync(item.tempPath, item.path);
219	      replacement.installed = true;
220	    }
221	  } catch (error) {
222	    let rollbackError = null;
223	    for (const item of [...replacements].reverse()) {
224	      try {
225	        if (item.installed) removeIfPresent(fileSystem, item.path);
226	        if (item.hadOriginal && fileSystem.existsSync(item.backupPath)) {
227	          fileSystem.renameSync(item.backupPath, item.path);
228	        }
229	      } catch (currentError) {
230	        rollbackError ??= currentError;
231	      }
232	    }
233	    for (const item of prepared) {
234	      try {
235	        removeIfPresent(fileSystem, item.tempPath);
236	      } catch (currentError) {
237	        rollbackError ??= currentError;
238	      }
239	    }
240	    const cause = error?.message || String(error);
241	    const detail = rollbackError
242	      ? `配置原子写入失败：${cause}；且回滚未能完整完成`
243	      : `配置原子写入失败：${cause}；原配置已保留`;
244	    throw new SetupStageError('配置写入', detail, '检查配置目录权限后重新运行 vibe-usage-quote0 enable');
245	  }
246	
247	  let cleanupError = null;
248	  for (const item of replacements) {
249	    if (!item.hadOriginal) continue;
250	    try {
251	      removeIfPresent(fileSystem, item.backupPath);
252	    } catch (error) {
253	      cleanupError ??= error;
254	    }
255	  }
