124	export function installMacosLaunchAgent(options = {}) {
125	  const intervalMinutes = normalizeIntervalMinutes(options.intervalMinutes);
126	  const uid = options.uid ?? process.getuid?.();
127	  if (!Number.isInteger(uid)) throw new Error('无法确定当前用户，不能安装 launchd 任务');
128	  const plistPath = launchAgentPath(options);
129	  const { plist, stateDirectory } = renderLaunchAgent(intervalMinutes, options);
130	  const fileSystem = options.fileSystem ?? nodeFs;
131	  fileSystem.mkdirSync(stateDirectory, { recursive: true, mode: 0o700 });
132	  writeFileAtomically(plistPath, plist, {
133	    ...options,
134	    validate(path) {
135	      runProcess('plutil', ['-lint', path], options, '生成的 launchd plist 校验失败');
136	    },
137	  });
138	
139	  const domain = `gui/${uid}`;
140	  const service = `${domain}/${LAUNCHD_LABEL}`;
141	  const spawn = options.spawnSyncImpl ?? spawnSync;
142	  const current = spawn('launchctl', ['print', service], {
143	    encoding: 'utf8',
144	    env: options.env ?? process.env,
145	  });
146	  if (current.error) throw new Error(`无法检查现有 launchd 任务：${current.error.message}`);
147	  if (current.status === 0) {
148	    runProcess('launchctl', ['bootout', service], options, '无法卸载现有 launchd 任务');
149	  }
150	  runProcess('launchctl', ['bootstrap', domain, plistPath], options, '无法加载 launchd 任务');
151	  return { platform: 'darwin', installed: true, plistPath, intervalMinutes };
152	}
153	
154	function systemdQuote(value) {
155	  const normalized = String(value);
156	  if (/[\0\r\n]/.test(normalized)) throw new Error('systemd 路径或环境变量包含不支持的控制字符');
157	  return `"${normalized
158	    .replaceAll('\\', '\\\\')
159	    .replaceAll('"', '\\"')
160	    .replaceAll('%', '%%')}"`;
161	}
162	
163	export function linuxSystemdPaths(options = {}) {
164	  const env = options.env ?? process.env;
165	  const root = env.XDG_CONFIG_HOME ?? join(options.home ?? homedir(), '.config');
166	  const directory = options.systemdDirectory ?? join(root, 'systemd', 'user');
167	  return {
168	    directory,
169	    servicePath: options.servicePath ?? join(directory, `${SYSTEMD_NAME}.service`),
170	    timerPath: options.timerPath ?? join(directory, `${SYSTEMD_NAME}.timer`),
171	  };
172	}
173	
174	function renderSystemdService(options = {}) {
175	  const env = options.env ?? process.env;
176	  const environment = scheduledEnvironment(env)
177	    .map(([name, value]) => `Environment=${systemdQuote(`${name}=${value}`)}`)
178	    .join('\n');
179	  return `[Unit]
180	Description=Push Vibe Usage to Quote/0
181	
182	[Service]
183	Type=oneshot
184	${environment ? `${environment}\n` : ''}WorkingDirectory=${systemdQuote(options.home ?? homedir())}
185	ExecStart=${systemdQuote(options.nodePath ?? process.execPath)} ${systemdQuote(options.cliPath ?? CLI_PATH)} push
186	`;
187	}
188	
189	function renderSystemdTimer(intervalMinutes) {
190	  return `[Unit]
191	Description=Refresh Vibe Usage on Quote/0
192	
193	[Timer]
194	OnStartupSec=1min
195	OnUnitActiveSec=${intervalMinutes}min
196	AccuracySec=1min
197	Unit=${SYSTEMD_NAME}.service
198	
199	[Install]
200	WantedBy=timers.target
201	`;
202	}
203	
204	export function installLinuxSystemdTimer(options = {}) {
205	  const intervalMinutes = normalizeIntervalMinutes(options.intervalMinutes);
206	  const paths = linuxSystemdPaths(options);
207	  writeFileAtomically(paths.servicePath, renderSystemdService(options), options);
208	  writeFileAtomically(paths.timerPath, renderSystemdTimer(intervalMinutes), options);
209	  runProcess('systemctl', ['--user', 'daemon-reload'], options, '无法重载 systemd 用户配置');
210	  runProcess(
211	    'systemctl',
212	    ['--user', 'enable', '--now', `${SYSTEMD_NAME}.timer`],
213	    options,
214	    '无法启用 systemd 用户定时任务',
215	  );
216	  return { platform: 'linux', installed: true, ...paths, intervalMinutes };
217	}
218	
219	export function installScheduledTask(options = {}) {
220	  const platform = options.platform ?? process.platform;
221	  const intervalMinutes = normalizeIntervalMinutes(options.intervalMinutes);
222	  if (platform === 'darwin') return installMacosLaunchAgent({ ...options, intervalMinutes });
223	  if (platform === 'linux') return installLinuxSystemdTimer({ ...options, intervalMinutes });
224	  if (platform !== 'win32') throw new Error(`当前平台不支持自动刷新：${platform}`);
225	
226	  const result = runProcess('powershell.exe', [
227	    '-NoLogo',
228	    '-NoProfile',
229	    '-NonInteractive',
230	    '-ExecutionPolicy',
231	    'Bypass',
232	    '-File',
233	    options.windowsScriptPath ?? WINDOWS_INSTALL_SCRIPT,
234	    '-IntervalMinutes',
235	    String(intervalMinutes),
240	  return { platform, installed: true, intervalMinutes, output: String(result.stdout) };
241	}
242	
243	function updateLinuxSystemdTimer(intervalMinutes, options = {}) {
244	  const paths = linuxSystemdPaths(options);
245	  const fileSystem = options.fileSystem ?? nodeFs;
246	  if (!fileSystem.existsSync(paths.timerPath)) {
247	    return { platform: 'linux', installed: false, updated: false, ...paths };
248	  }
249	  writeFileAtomically(paths.timerPath, renderSystemdTimer(intervalMinutes), options);
250	  runProcess('systemctl', ['--user', 'daemon-reload'], options, '无法重载 systemd 用户配置');
251	  runProcess(
252	    'systemctl',
253	    ['--user', 'restart', `${SYSTEMD_NAME}.timer`],
254	    options,
255	    '无法重启 systemd 用户定时任务',
256	  );
257	  return { platform: 'linux', installed: true, updated: true, ...paths };
258	}
259	
260	export function updateInstalledSchedule(intervalMinutes, options = {}) {
261	  const minutes = normalizeIntervalMinutes(intervalMinutes);
262	  const platform = options.platform ?? process.platform;
263	
264	  if (platform === 'win32') {
265	    const result = runProcess('powershell.exe', [
266	      '-NoLogo',
267	      '-NoProfile',
268	      '-NonInteractive',
269	      '-ExecutionPolicy',
270	      'Bypass',
271	      '-File',
272	      options.windowsScriptPath ?? WINDOWS_UPDATE_SCRIPT,
273	      '-IntervalMinutes',
274	      String(minutes),
275	    ], {
276	      ...options,
277	      env: windowsPowerShellEnvironment(options.env),
278	    }, '无法更新 Windows 计划任务刷新间隔');
279	    const updated = /schedule_updated=true/i.test(String(result.stdout));
280	    return { platform, installed: updated, updated };
281	  }
282	
283	  if (platform === 'darwin') {
284	    const plistPath = launchAgentPath(options);
285	    const fileSystem = options.fileSystem ?? nodeFs;
286	    const fileExists = options.existsSyncImpl ?? ((path) => fileSystem.existsSync(path));
287	    if (!fileExists(plistPath)) return { platform, installed: false, updated: false, plistPath };
288	    runProcess('plutil', [
289	      '-replace',
290	      'StartInterval',
291	      '-integer',
292	      String(minutes * 60),
293	      plistPath,
294	    ], options, '无法更新 launchd plist 刷新间隔');
295	
296	    const uid = options.uid ?? process.getuid?.();
297	    if (!Number.isInteger(uid)) return { platform, installed: true, updated: true, loaded: false, plistPath };
298	    const domain = `gui/${uid}`;
299	    const spawn = options.spawnSyncImpl ?? spawnSync;
300	    const current = spawn('launchctl', ['print', `${domain}/${LAUNCHD_LABEL}`], {
301	      encoding: 'utf8',
302	      env: options.env ?? process.env,
303	    });
304	    if (current.error || current.status !== 0) {
305	      return { platform, installed: true, updated: true, loaded: false, plistPath };
306	    }
307	    runProcess('launchctl', ['bootout', `${domain}/${LAUNCHD_LABEL}`], options, '无法卸载旧的 launchd 任务');
308	    runProcess('launchctl', ['bootstrap', domain, plistPath], options, 'plist 已更新，但无法重新加载 launchd 任务');
309	    return { platform, installed: true, updated: true, loaded: true, plistPath };
310	  }
311	
312	  if (platform === 'linux') return updateLinuxSystemdTimer(minutes, options);
313	  return { platform, installed: false, updated: false, unsupported: true };
314	}
315	
316	function disableLinuxSystemdTimer(options = {}) {
317	  const paths = linuxSystemdPaths(options);
318	  const fileSystem = options.fileSystem ?? nodeFs;
319	  const installed = fileSystem.existsSync(paths.servicePath) || fileSystem.existsSync(paths.timerPath);
320	  if (!installed) return { platform: 'linux', disabled: false, absent: true, ...paths };
321	  runProcess(
322	    'systemctl',
323	    ['--user', 'disable', '--now', `${SYSTEMD_NAME}.timer`],
324	    options,
325	    '无法停用 systemd 用户定时任务',
326	  );
327	  if (fileSystem.existsSync(paths.timerPath)) fileSystem.unlinkSync(paths.timerPath);
328	  if (fileSystem.existsSync(paths.servicePath)) fileSystem.unlinkSync(paths.servicePath);
329	  runProcess('systemctl', ['--user', 'daemon-reload'], options, '任务已删除，但无法重载 systemd 用户配置');
330	  return { platform: 'linux', disabled: true, absent: false, ...paths };
331	}
332	
333	export function disableSchedule(options = {}) {
334	  const platform = options.platform ?? process.platform;
335	  if (platform === 'win32') {
336	    const result = runProcess('powershell.exe', [
337	      '-NoLogo',
338	      '-NoProfile',
339	      '-NonInteractive',
340	      '-ExecutionPolicy',
341	      'Bypass',
342	      '-File',
343	      options.windowsScriptPath ?? WINDOWS_UNINSTALL_SCRIPT,
344	    ], {
345	      ...options,
346	      env: windowsPowerShellEnvironment(options.env),
347	    }, '无法解除 Windows 计划任务');
348	    const output = String(result.stdout);
349	    return {
350	      platform,
351	      disabled: /uninstalled_task=/i.test(output),
352	      absent: /task_absent=/i.test(output),
353	    };
354	  }
355	
356	  if (platform === 'darwin') {
357	    const uid = options.uid ?? process.getuid?.();
358	    if (!Number.isInteger(uid)) throw new Error('无法确定当前用户，不能安全解除 launchd 任务');
359	    const service = `gui/${uid}/${LAUNCHD_LABEL}`;
360	    const spawn = options.spawnSyncImpl ?? spawnSync;
361	    const current = spawn('launchctl', ['print', service], {
362	      encoding: 'utf8',
363	      env: options.env ?? process.env,
364	    });
365	    if (current.error) throw new Error(`无法检查 launchd 任务：${current.error.message}`);
366	    const loaded = current.status === 0;
367	    if (loaded) runProcess('launchctl', ['bootout', service], options, '无法解除 launchd 任务');
368	
369	    const plistPath = launchAgentPath(options);
370	    const fileSystem = options.fileSystem ?? nodeFs;
371	    const fileExists = options.existsSyncImpl ?? ((path) => fileSystem.existsSync(path));
372	    const removeFile = options.unlinkSyncImpl ?? ((path) => fileSystem.unlinkSync(path));
373	    const installed = fileExists(plistPath);
374	    if (installed) removeFile(plistPath);
375	    return {
376	      platform,
377	      disabled: loaded || installed,
378	      loaded,
379	      removed: installed,
380	      absent: !loaded && !installed,
381	      plistPath,
382	    };
383	  }
384	
385	  if (platform === 'linux') return disableLinuxSystemdTimer(options);
386	  return { platform, disabled: false, absent: true, unsupported: true };
387	}

